\node [elli, above left of=Propregularityonsmalleropenset, xshift=-2em, yshift=-1.60em]
(LemmaderivativesofFunifbounded)
{\emph{Lemma \ref{Lemma all derivatives of F are unif bounded}}
\\$F_{H_{S}}$ uniformly bounded in $L_{k}^{\infty }\left( W_{S}\right),\;\forall k$
};
