$\hat{e}_{t} \leq \left(B\e{t}\right)\epsilon$
};
\path [seta]  (PropeHatDecaysExponentiallyWithS) -- (eqExpDecayC0);



\node [elli, above right of=CorHsTisinLp2, xshift=0.9em, yshift=8em] 
(CorHt->HTinC0)
