\node [elli, above of=CorHsTisinLp2,yshift=-5.5em, xshift=0em]
(CorBoundedFhat)
{\emph{Corollary \ref{Cor Bounded F hat}}
\\$\sup_{W_{S}}\vert\hat{F}_{H_{S}(t)}\vert^{2}\leq B$ 
};
\path [linha] (CorBoundedFhat) --   (MID-MorHt->HTinC0);

\node [cited,above of=PropeHatDecaysExponentiallyWithS,yshift=-5.1em,xshift=-0em]
(Lemmamaxprinciplemfdsw)
{\emph{Lemma \ref{Lemma max principle mfds w bdry}
}\\Maximum principle on compact manifolds with boundary
};
\path [seta] (Lemmamaxprinciplemfdsw) -- coordinate[midway](MID-Lemmamaxprinciplemfdsw)
(CorBoundedFhat);
\path [seta]  (Lemmamaxprinciplemfdsw) -- (PropeHatDecaysExponentiallyWithS);
