\node [cited, above right of=Lemmamaxprinciplemfdsw,xshift=7em,yshift=-4em]
(Weitzenbock)
{Weitzenb\"ock formula};
\path [seta] (Weitzenbock) -- + (-1.8,0) -| (MID-Lemmamaxprinciplemfdsw);

\node [equation, above of=Weitzenbock, yshift=-9em]
(Dirichlet)
{(\ref{Dirichlet})};
\path [linha] (Dirichlet) -- + (-1,0) -| (MID-Lemmamaxprinciplemfdsw);

\node [cited, above of=Lemmamaxprinciplemfdsw, yshift=5em]
(Lemmamaxprinforsigma)
{\emph{Lemma \ref{Lemma max prin for sigma}}
\\$\left( \frac{d}{dt}+\Delta \right) \sigma \leq 0$ 
};
\path [seta] (Lemmamaxprinforsigma) -- +(0,-1)|- coordinate[midway](MID-Lemmamaxprinforsigma)
