\path [linha] (Lemmamaxprinciplemfdsw) -- +(0,1) |- (CorHt->HTinC0);

\node [elli,right of=Lemmamaxprinforsigma, yshift=-1em,xshift=3.5em]
(Prop-shorttimeexistence)
