\\$H_S(t)$ exists, for $t\in[0,\varepsilon[$
};
\path [seta] (Prop-shorttimeexistence) -- (CorHt->HTinC0);

\node [elli, above right of=CorHt->HTinC0, yshift=-1.5em,xshift=-3em]
(remarks)
{\emph{\emph{\emph{Remarks \ref{Rem Co norm is complete}} and \emph{\ref{Rem conv sigma => conv lambda}}}}};
\path [seta] (remarks) -- (CorHt->HTinC0);

\end{scriptsize}
